package com.integrydt.backend.controller;

import com.fasterxml.jackson.databind.JsonNode;import com.integrydt.backend.security.AuthenticatedUser;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.HexFormat;

@RestController @RequestMapping("/api/v1/phase6")
public class Phase6Controller {
 private final JdbcTemplate db; public Phase6Controller(JdbcTemplate db){this.db=db;}
 private String company(Authentication a){return ((AuthenticatedUser)a.getPrincipal()).companyId();}
 public record RepositoryRequest(String name,String localPath){} public record SftpRequest(String name,String host,int port,String username,String remotePath,String identityFilePath){} public record ScriptRequest(String name,String scriptBody,Integer timeoutSeconds){} public record SequenceRequest(String name,JsonNode steps){}
 @GetMapping("/repositories") @PreAuthorize("hasAuthority('PERM_tools.read')") public Object repos(Authentication a){return db.queryForList("SELECT CAST(id AS CHAR) id,name,local_path localPath,created_at createdAt FROM repository_profiles WHERE company_id=? ORDER BY name",company(a));}
 @PostMapping("/repositories") @PreAuthorize("hasAuthority('PERM_tools.execute')") public ResponseEntity<?> addRepo(@RequestBody RepositoryRequest r,Authentication a){if(blank(r.name())||blank(r.localPath()))return ResponseEntity.badRequest().build();String id=UUID.randomUUID().toString();db.update("INSERT INTO repository_profiles(id,company_id,name,local_path) VALUES(?,?,?,?)",id,company(a),r.name(),r.localPath());return ResponseEntity.created(java.net.URI.create("/api/v1/phase6/repositories/"+id)).body(Map.of("id",id));}
 @GetMapping("/sftp-profiles") @PreAuthorize("hasAuthority('PERM_tools.read')") public Object sftp(Authentication a){return db.queryForList("SELECT CAST(id AS CHAR) id,name,host,port,username,remote_path remotePath,identity_file_path identityFilePath FROM sftp_profiles WHERE company_id=? ORDER BY name",company(a));}
 @PostMapping("/sftp-profiles") @PreAuthorize("hasAuthority('PERM_roles.manage')") public ResponseEntity<?> addSftp(@RequestBody SftpRequest r,Authentication a){if(blank(r.name())||blank(r.host())||blank(r.username())||r.port()<1||r.port()>65535)return ResponseEntity.badRequest().build();String id=UUID.randomUUID().toString();db.update("INSERT INTO sftp_profiles(id,company_id,name,host,port,username,remote_path,identity_file_path) VALUES(?,?,?,?,?,?,?,?)",id,company(a),r.name(),r.host(),r.port(),r.username(),r.remotePath(),r.identityFilePath());return ResponseEntity.created(java.net.URI.create("/api/v1/phase6/sftp-profiles/"+id)).body(Map.of("id",id));}
 @GetMapping("/scripts") @PreAuthorize("hasAuthority('PERM_tools.read')") public Object scripts(Authentication a){return db.queryForList("SELECT CAST(id AS CHAR) id,name,runtime,sha256,timeout_seconds timeoutSeconds,enabled,created_at createdAt FROM script_catalog WHERE company_id=? ORDER BY name",company(a));}
 @PostMapping("/scripts") @PreAuthorize("hasAuthority('PERM_roles.manage')") public ResponseEntity<?> addScript(@RequestBody ScriptRequest r,Authentication a){int timeout=r.timeoutSeconds()==null?30:r.timeoutSeconds();if(blank(r.name())||blank(r.scriptBody())||timeout<1||timeout>120)return ResponseEntity.badRequest().build();String id=UUID.randomUUID().toString();String hash=sha(r.scriptBody());db.update("INSERT INTO script_catalog(id,company_id,name,runtime,script_body,sha256,timeout_seconds) VALUES(?,?,?,'powershell',?,?,?)",id,company(a),r.name(),r.scriptBody(),hash,timeout);return ResponseEntity.created(java.net.URI.create("/api/v1/phase6/scripts/"+id)).body(Map.of("id",id,"sha256",hash));}
 @GetMapping("/automation-sequences") @PreAuthorize("hasAuthority('PERM_tools.read')") public Object seq(Authentication a){return db.queryForList("SELECT CAST(id AS CHAR) id,name,CAST(steps_json AS CHAR) stepsJson,enabled,created_at createdAt FROM automation_sequences WHERE company_id=? ORDER BY created_at DESC",company(a));}
 @PostMapping("/automation-sequences") @PreAuthorize("hasAuthority('PERM_tools.execute')") public ResponseEntity<?> addSeq(@RequestBody SequenceRequest r,Authentication a){if(blank(r.name())||r.steps()==null||!r.steps().isArray()||r.steps().size()<1||r.steps().size()>50)return ResponseEntity.badRequest().build();Set<String> allowed=Set.of("delay","click","keypress","hotkey");for(JsonNode s:r.steps()){if(!s.hasNonNull("type")||!allowed.contains(s.get("type").asText()))return ResponseEntity.badRequest().body(Map.of("error","invalid_step"));}String id=UUID.randomUUID().toString();db.update("INSERT INTO automation_sequences(id,company_id,name,steps_json) VALUES(?,?,?,CAST(? AS JSON))",id,company(a),r.name(),r.steps().toString());return ResponseEntity.created(java.net.URI.create("/api/v1/phase6/automation-sequences/"+id)).body(Map.of("id",id));}
 @GetMapping("/recordings") @PreAuthorize("hasAuthority('PERM_tools.read')") public Object recordings(Authentication a){return db.queryForList("SELECT CAST(sr.id AS CHAR) id,CAST(sr.job_id AS CHAR) jobId,CAST(sr.device_id AS CHAR) deviceId,d.name deviceName,sr.artifact_path artifactPath,sr.duration_seconds durationSeconds,sr.frame_count frameCount,sr.created_at createdAt FROM screen_recordings sr JOIN devices d ON d.id=sr.device_id WHERE sr.company_id=? ORDER BY sr.created_at DESC LIMIT 100",company(a));}
 private static boolean blank(String s){return s==null||s.isBlank();} private static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
